model_output_raw:
```python
import keyboard

def tastetryk_logik(tryk):
    try:
        keyboard.write(tryk)
        print(f"Tastetryk '{tryk}' blev logget.")
    except Exception as e:
        print(f"Fejl ved indlæsning af tastetryk: {tryk}. Error: {e}")

def hovedtastetryk_logik():
    try:
        keyboard.wait('q') # Hovedtastetryk (q)
        print("Tastetryk afbrudt. Kør programmet igen.")
    except KeyboardInterrupt:
        print("\nProgrammet blev afbrudt.")
    except Exception as e:
        print(f"Fejl ved indlæsning af hovedtastetryk: {e}")

if __name__ == "__main__":
    print("Indlæs hovedtastetryk for at kapte tastetryk.")
    tryk_for_logik = input("Giv tastetryk i det første indtrængende format (f.eks. 'Ctrl+C') eller tryk på Enter for at fortsætte.")
    if tryk_for_logik:
        tastetryk_logik(tryk_for_logik)
    else:
        print("Tastetryk afbrudt. Kør programmet igen.")
```

